insert into kafaa_leadership_behaviours (id, form_from, sort, trait_id, title_en, title_ar, short_en, short_ar, statement_en, statement_ar, framework_en, framework_ar, anchors, coach, links, programme_ids, benchmark_ids, sources) values
('b-safety-values', 1, 10, 'trait-4', 'Safety values and actions', 'قيم السلامة وأفعالها', 'Safety values', 'قيم السلامة', 'Puts nuclear safety first in words and decisions, even under schedule pressure.', 'يضع السلامة النووية أولاً في الأقوال والقرارات حتى تحت ضغط الجدول.', 'INPO 12-012 safety-culture trait 4: leadership safety values and actions', 'سمة ثقافة السلامة 4 في INPO 12-012: قيم السلامة القيادية وأفعالها', '{"1":{"en":"Lets schedule or cost pressure override safety in words or decisions.","ar":"يسمح لضغط الجدول أو التكلفة بأن يتقدّم على السلامة في الأقوال أو القرارات."},"2":{"en":"Talks about safety but sends mixed signals when the work is behind.","ar":"يتحدث عن السلامة لكنه يرسل إشارات متضاربة عندما يتأخر العمل."},"3":{"en":"Puts safety first in briefs and decisions, including under schedule pressure.","ar":"يضع السلامة أولاً في الإحاطات والقرارات، حتى تحت ضغط الجدول."},"4":{"en":"Visibly stops or slows work for safety and explains why to the team.","ar":"يوقف العمل أو يبطئه علناً من أجل السلامة ويشرح السبب للفريق."},"5":{"en":"Sets the standard across teams; others quote their safety decisions as examples.","ar":"يضع المعيار عبر الفرق، ويستشهد الآخرون بقراراته المتعلقة بالسلامة كأمثلة."}}'::jsonb, '{"tips":[{"en":"Open your next brief with the one thing that must not be traded for time.","ar":"افتتح إحاطتك القادمة بالأمر الوحيد الذي لا يجوز التنازل عنه مقابل الوقت."},{"en":"When you slow a job for safety, say so out loud and say why.","ar":"عندما تبطئ عملاً من أجل السلامة، قل ذلك بصوت مسموع واذكر السبب."}],"practice":{"en":"This week: ask your team which pressure most often competes with safety, and agree one response.","ar":"هذا الأسبوع: اسأل فريقك عن أكثر ضغط يتنافس مع السلامة، واتفقوا على استجابة واحدة."},"watch":{"en":"Silence under schedule pressure reads as permission.","ar":"الصمت تحت ضغط الجدول يُفهم كإذن."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"},{"to":"/my/safety-culture","label_en":"My safety culture","label_ar":"ثقافة السلامة لديّ"}]'::jsonb, array['prog-cld','prog-fas','prog-future-leaders','prog-inpo','prog-intilaqa','prog-let','prog-masterclass','prog-one']::text[], '{}'::text[], '[]'::jsonb),
('b-accountability', 1, 20, 'trait-1', 'Personal accountability', 'المساءلة الشخصية', 'Accountability', 'المساءلة', 'Owns outcomes, follows through and holds the standard for themselves first.', 'يتحمل مسؤولية النتائج ويتابع حتى النهاية ويلتزم بالمعيار بنفسه أولاً.', 'INPO 12-012 safety-culture trait 1: personal accountability', 'سمة ثقافة السلامة 1 في INPO 12-012: المساءلة الشخصية', '{"1":{"en":"Blames others or circumstances when things go wrong.","ar":"يلوم الآخرين أو الظروف عندما تسوء الأمور."},"2":{"en":"Owns their own tasks but not the outcome for the team.","ar":"يتحمل مسؤولية مهامه لكن لا يتحمل نتيجة الفريق."},"3":{"en":"Owns outcomes, follows through on commitments and holds themselves to the standard.","ar":"يتحمل مسؤولية النتائج ويفي بالتزاماته ويلتزم بالمعيار بنفسه."},"4":{"en":"Admits mistakes openly and fixes the system, not just the symptom.","ar":"يعترف بالأخطاء علناً ويصلح النظام لا العَرَض فقط."},"5":{"en":"Builds a team where everyone owns the standard without being told.","ar":"يبني فريقاً يتحمل فيه الجميع مسؤولية المعيار دون توجيه."}}'::jsonb, '{"tips":[{"en":"Close every commitment you make in a meeting: done, changed or dropped, and tell people which.","ar":"أغلق كل التزام تقطعه في اجتماع: أُنجز أو تغيّر أو أُلغي، وأخبر الناس بذلك."},{"en":"Name your own part first in any post-job review.","ar":"اذكر دورك أنت أولاً في أي مراجعة بعد العمل."}],"practice":{"en":"This week: list three open commitments and close one with the people who depend on it.","ar":"هذا الأسبوع: اكتب ثلاثة التزامات مفتوحة وأغلق واحداً منها مع من يعتمدون عليه."},"watch":{"en":"Accountability is not blame: fix the system as well as the slip.","ar":"المساءلة ليست لوماً: أصلح النظام إلى جانب الخطأ."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-estadad','prog-exec-coaching','prog-hipo-coaching']::text[], '{}'::text[], '[]'::jsonb),
('b-questioning', 1, 30, 'trait-2', 'Questioning attitude', 'الموقف التساؤلي', 'Questioning', 'التساؤل', 'Challenges assumptions and stops when unsure; invites others to do the same.', 'يتحدى الافتراضات ويتوقف عند الشك ويدعو الآخرين إلى فعل ذلك.', 'INPO 12-012 safety-culture trait 2: questioning attitude', 'سمة ثقافة السلامة 2 في INPO 12-012: الموقف التساؤلي', '{"1":{"en":"Proceeds on assumptions and discourages questions.","ar":"يمضي بناءً على افتراضات ويثبّط الأسئلة."},"2":{"en":"Asks questions when prompted; rarely stops when unsure.","ar":"يسأل عند التنبيه، ونادراً ما يتوقف عند الشك."},"3":{"en":"Challenges assumptions and stops when unsure.","ar":"يتحدى الافتراضات ويتوقف عند الشك."},"4":{"en":"Invites challenge from the team and thanks people who stop the job.","ar":"يدعو الفريق إلى التحدي ويشكر من يوقف العمل."},"5":{"en":"Makes a questioning attitude a team habit that others learn from.","ar":"يجعل الموقف التساؤلي عادة لدى الفريق يتعلم منها الآخرون."}}'::jsonb, '{"tips":[{"en":"Ask \"what would make this go wrong?\" before every non-routine task.","ar":"اسأل \"ما الذي قد يجعل هذا يسوء؟\" قبل كل مهمة غير اعتيادية."},{"en":"Thank the first person who stops a job, even when the job was fine.","ar":"اشكر أول من يوقف العمل، حتى لو كان العمل سليماً."}],"practice":{"en":"This week: in one brief, ask the most junior person for the risk they see first.","ar":"هذا الأسبوع: في إحاطة واحدة، اسأل أحدث الحاضرين أولاً عن الخطر الذي يراه."},"watch":{"en":"Familiar tasks are where assumptions hide.","ar":"المهام المألوفة هي حيث تختبئ الافتراضات."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"},{"to":"/my/ai-fluency/drills","label_en":"Governed AI drills","label_ar":"تمارين الذكاء الاصطناعي المنضبطة"}]'::jsonb, '{}'::text[], '{}'::text[], '[]'::jsonb),
('b-communication', 1, 40, 'trait-3', 'Effective safety communication', 'التواصل الفعّال بشأن السلامة', 'Communication', 'التواصل', 'Communicates clearly and checks understanding, in briefs and turnovers.', 'يتواصل بوضوح ويتحقق من الفهم في الإحاطات وتسليم الورديات.', 'INPO 12-012 safety-culture trait 3: effective safety communication', 'سمة ثقافة السلامة 3 في INPO 12-012: التواصل الفعّال بشأن السلامة', '{"1":{"en":"Briefs are unclear or skipped, and understanding is not checked.","ar":"الإحاطات غير واضحة أو تُتخطّى، ولا يُتحقق من الفهم."},"2":{"en":"Communicates the basics but rarely checks understanding.","ar":"يوصل الأساسيات لكنه نادراً ما يتحقق من الفهم."},"3":{"en":"Communicates clearly and checks understanding in briefs and turnovers.","ar":"يتواصل بوضوح ويتحقق من الفهم في الإحاطات وتسليم الورديات."},"4":{"en":"Uses three-way communication and adapts the message to the audience.","ar":"يستخدم التواصل الثلاثي ويكيّف الرسالة مع الجمهور."},"5":{"en":"Coaches others on safety communication; their team''s turnovers are a model.","ar":"يدرّب الآخرين على التواصل بشأن السلامة، وتسليم ورديات فريقه نموذج يُحتذى."}}'::jsonb, '{"tips":[{"en":"End each brief by asking one person to repeat the key risk in their own words.","ar":"اختم كل إحاطة بأن تطلب من شخص إعادة الخطر الرئيسي بكلماته."},{"en":"Use the same turnover structure every shift so gaps stand out.","ar":"استخدم بنية التسليم نفسها في كل وردية حتى تظهر الفجوات."}],"practice":{"en":"This week: observe one turnover and give the pair one piece of specific feedback.","ar":"هذا الأسبوع: راقب تسليماً واحداً وقدّم للطرفين ملاحظة محددة واحدة."},"watch":{"en":"A nod is not confirmation.","ar":"الإيماءة ليست تأكيداً."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-estadad','prog-intilaqa','prog-let']::text[], '{}'::text[], '[]'::jsonb),
('b-decisions', 1, 50, 'trait-5', 'Conservative decision-making', 'اتخاذ القرار المتحفظ', 'Decisions', 'القرارات', 'Makes decisions that are systematic, conservative and explained to the team.', 'يتخذ قرارات منهجية ومتحفظة ويشرحها للفريق.', 'INPO 12-012 safety-culture trait 5: decision-making', 'سمة ثقافة السلامة 5 في INPO 12-012: اتخاذ القرار', '{"1":{"en":"Makes quick decisions without considering the margin to safety.","ar":"يتخذ قرارات سريعة دون مراعاة هامش السلامة."},"2":{"en":"Considers risk but rarely explains the decision.","ar":"يراعي المخاطر لكنه نادراً ما يشرح القرار."},"3":{"en":"Makes systematic, conservative decisions and explains them to the team.","ar":"يتخذ قرارات منهجية ومتحفظة ويشرحها للفريق."},"4":{"en":"Seeks other views before deciding and chooses the safer path under uncertainty.","ar":"يستطلع آراء أخرى قبل القرار ويختار المسار الأكثر أماناً عند عدم اليقين."},"5":{"en":"Others seek them out for difficult decisions, and their decisions are reviewed and learned from.","ar":"يلجأ إليه الآخرون في القرارات الصعبة، وتُراجَع قراراته ويُتعلَّم منها."}}'::jsonb, '{"tips":[{"en":"Say what you do not know before you decide.","ar":"قل ما لا تعرفه قبل أن تقرر."},{"en":"When two options look equal, pick the one that keeps more margin and say so.","ar":"عندما يبدو خياران متساويين، اختر الذي يحافظ على هامش أكبر وصرّح بذلك."}],"practice":{"en":"This week: write down one recent decision, the options you rejected and why; share it with your team.","ar":"هذا الأسبوع: دوّن قراراً حديثاً والخيارات التي رفضتها وسبب ذلك، وشاركه مع فريقك."},"watch":{"en":"Confidence is not evidence.","ar":"الثقة ليست دليلاً."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-exec-coaching','prog-inpo','prog-let']::text[], '{}'::text[], '[]'::jsonb),
('b-respect', 1, 60, 'trait-6', 'Respectful work environment', 'بيئة عمل محترمة', 'Respect', 'الاحترام', 'Treats people with dignity and builds trust across teams.', 'يعامل الناس بكرامة ويبني الثقة بين الفرق.', 'INPO 12-012 safety-culture trait 6: respectful work environment', 'سمة ثقافة السلامة 6 في INPO 12-012: بيئة عمل محترمة', '{"1":{"en":"Dismisses or embarrasses people.","ar":"يتجاهل الآخرين أو يحرجهم."},"2":{"en":"Polite, but trust stays low across teams.","ar":"مهذب، لكن الثقة بين الفرق تبقى منخفضة."},"3":{"en":"Treats people with dignity and builds trust across teams.","ar":"يعامل الناس بكرامة ويبني الثقة بين الفرق."},"4":{"en":"Resolves conflict fairly and recognises others'' contributions.","ar":"يحل الخلافات بإنصاف ويقدّر مساهمات الآخرين."},"5":{"en":"Creates a climate of trust that people describe as a reason to stay.","ar":"يخلق مناخاً من الثقة يصفه الناس بأنه سبب للبقاء."}}'::jsonb, '{"tips":[{"en":"Recognise one specific contribution in public each week.","ar":"قدّر مساهمة محددة علناً كل أسبوع."},{"en":"Deal with disrespect the same day, in private.","ar":"تعامل مع عدم الاحترام في اليوم نفسه وعلى انفراد."}],"practice":{"en":"This week: thank a colleague from another team for something that helped yours.","ar":"هذا الأسبوع: اشكر زميلاً من فريق آخر على أمر ساعد فريقك."},"watch":{"en":"Jokes at someone''s expense close mouths.","ar":"النكات على حساب الآخرين تُسكت الأفواه."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-intilaqa','prog-masterclass','prog-one']::text[], '{}'::text[], '[]'::jsonb),
('b-learning', 1, 70, 'trait-7', 'Continuous learning', 'التعلم المستمر', 'Learning', 'التعلم', 'Seeks feedback, learns from experience and develops others.', 'يسعى إلى الملاحظات ويتعلم من التجربة ويطوّر الآخرين.', 'INPO 12-012 safety-culture trait 7: continuous learning', 'سمة ثقافة السلامة 7 في INPO 12-012: التعلم المستمر', '{"1":{"en":"Avoids feedback and repeats the same mistakes.","ar":"يتجنب الملاحظات ويكرر الأخطاء نفسها."},"2":{"en":"Accepts feedback when given; learning stays personal.","ar":"يقبل الملاحظات عندما تُقدَّم، ويبقى التعلم شخصياً."},"3":{"en":"Seeks feedback, learns from experience and develops others.","ar":"يسعى إلى الملاحظات ويتعلم من التجربة ويطوّر الآخرين."},"4":{"en":"Uses operating experience to change how the team works.","ar":"يستخدم الخبرة التشغيلية لتغيير طريقة عمل الفريق."},"5":{"en":"Builds a learning organisation: lessons spread beyond their own team.","ar":"يبني مؤسسة متعلمة تنتشر فيها الدروس خارج فريقه."}}'::jsonb, '{"tips":[{"en":"Ask for one piece of feedback after every significant task.","ar":"اطلب ملاحظة واحدة بعد كل مهمة مهمة."},{"en":"Share one operating-experience lesson in each team meeting.","ar":"شارك درساً واحداً من الخبرة التشغيلية في كل اجتماع للفريق."}],"practice":{"en":"This week: pick one lesson from operating experience and change one thing your team does.","ar":"هذا الأسبوع: اختر درساً من الخبرة التشغيلية وغيّر أمراً واحداً يفعله فريقك."},"watch":{"en":"Learning that is not shared is lost at the next shift change.","ar":"التعلم الذي لا يُشارك يضيع عند تغيير الوردية التالي."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"},{"to":"/knowledge","label_en":"Knowledge library","label_ar":"مكتبة المعرفة"}]'::jsonb, array['prog-cld','prog-estadad','prog-hipo-coaching','prog-mentoring','prog-one']::text[], '{}'::text[], '[]'::jsonb),
('b-concerns', 1, 80, 'trait-9', 'Environment for raising concerns', 'بيئة طرح المخاوف', 'Raising concerns', 'طرح المخاوف', 'Makes it easy and safe for anyone to raise a concern, and acts on it.', 'يجعل طرح المخاوف سهلاً وآمناً للجميع ويتصرف بناءً عليها.', 'INPO 12-012 safety-culture trait 9: environment for raising concerns', 'سمة ثقافة السلامة 9 في INPO 12-012: بيئة طرح المخاوف', '{"1":{"en":"People hesitate to raise concerns with them.","ar":"يتردد الناس في طرح مخاوفهم عليه."},"2":{"en":"Listens to concerns but rarely closes the loop.","ar":"يستمع إلى المخاوف لكنه نادراً ما يعود إلى صاحبها بما تم."},"3":{"en":"Makes it easy and safe to raise a concern, and acts on it.","ar":"يجعل طرح المخاوف سهلاً وآمناً ويتصرف بناءً عليها."},"4":{"en":"Thanks people for concerns, reports back on actions and protects them from blame.","ar":"يشكر من يطرح المخاوف ويبلغهم بالإجراءات ويحميهم من اللوم."},"5":{"en":"Concerns are raised early across the area because people trust the response.","ar":"تُطرح المخاوف مبكراً في نطاق عمله لأن الناس يثقون بالاستجابة."}}'::jsonb, '{"tips":[{"en":"Report back on every concern within a week, even if the answer is \"not yet\".","ar":"عُد بإجابة عن كل مخوف خلال أسبوع، حتى لو كانت \"ليس بعد\"."},{"en":"Remind the team of every channel, including the confidential one.","ar":"ذكّر الفريق بكل القنوات، بما فيها القناة السرية."}],"practice":{"en":"This week: ask your team what would make raising a concern easier, and act on one answer.","ar":"هذا الأسبوع: اسأل فريقك عما يسهّل طرح المخاوف، ونفّذ إجابة واحدة."},"watch":{"en":"How you react to the first concern decides whether there is a second.","ar":"ردّ فعلك على أول مخوف يحدد ما إذا كان سيأتي ثانٍ."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-fas','prog-mentoring']::text[], '{}'::text[], '[]'::jsonb),
('b-digital-change', 2, 90, null, 'Leading digital change', 'قيادة التحول الرقمي', 'Digital change', 'التحول الرقمي', 'Explains why a digital change matters for safety and the work, involves the people who will use it, and keeps a proven fallback until the new way works.', 'يشرح لماذا يهم التغيير الرقمي للسلامة وللعمل، ويشرك من سيستخدمونه، ويُبقي بديلاً مجرّباً حتى تثبت الطريقة الجديدة.', 'WEF Future of Jobs 2025: technological literacy is among the fastest-growing skills (per source)', 'تقرير مستقبل الوظائف 2025 للمنتدى الاقتصادي العالمي: الإلمام التقني من أسرع المهارات نمواً (وفق المصدر)', '{"1":{"en":"Avoids or resists digital change and leaves the team to work it out.","ar":"يتجنب التغيير الرقمي أو يقاومه ويترك الفريق ليتدبر أمره."},"2":{"en":"Supports changes others lead but rarely explains them to the team.","ar":"يدعم تغييرات يقودها غيره لكنه نادراً ما يشرحها للفريق."},"3":{"en":"Explains the reason for a change, plans the training and checks that it works in practice.","ar":"يشرح سبب التغيير ويخطط للتدريب ويتحقق من نجاحه عملياً."},"4":{"en":"Involves users early, pilots the change with clear stop criteria and keeps a fallback until it is proven.","ar":"يشرك المستخدمين مبكراً ويجرّب التغيير بمعايير توقف واضحة ويُبقي بديلاً حتى يثبت."},"5":{"en":"Shapes the digital roadmap with the team, measures the benefit for safety and the work, and coaches other leaders to do the same.","ar":"يشكّل خارطة الطريق الرقمية مع الفريق ويقيس الفائدة للسلامة والعمل ويدرّب القادة الآخرين على ذلك."}}'::jsonb, '{"tips":[{"en":"Before a rollout, write one sentence on the problem it solves for the team and one on what will not change.","ar":"قبل أي إطلاق، اكتب جملة عن المشكلة التي يحلها للفريق وجملة عما لن يتغير."},{"en":"Name the fallback: the old route stays until two clean weeks on the new one.","ar":"حدّد البديل: يبقى المسار القديم حتى أسبوعين نظيفين على الجديد."},{"en":"Ask the newest and the most experienced user to test it first, and listen to both.","ar":"اطلب من أحدث مستخدم وأكثرهم خبرة أن يختبراه أولاً، واستمع إلى كليهما."}],"practice":{"en":"This week: run a 15-minute walk-through of one digital tool with your team and capture three questions.","ar":"هذا الأسبوع: قدّم عرضاً لمدة 15 دقيقة لأداة رقمية واحدة مع فريقك ودوّن ثلاثة أسئلة."},"watch":{"en":"Do not measure success by go-live dates alone.","ar":"لا تقِس النجاح بمواعيد الإطلاق وحدها."}}'::jsonb, '[{"to":"/learn/future-skills","label_en":"Future-skills course pack","label_ar":"حزمة دورات المهارات المستقبلية"},{"to":"/my/ai-fluency","label_en":"My AI fluency","label_ar":"طلاقتي في الذكاء الاصطناعي"},{"to":"/opportunities/future","label_en":"Future-skills gigs","label_ar":"مهام المهارات المستقبلية"}]'::jsonb, array['prog-future-leaders']::text[], array['WEF-FOJ']::text[], '[{"label":"WEF · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb),
('b-ai-teams', 2, 100, 'trait-2', 'Leading AI-augmented teams', 'قيادة فرق معززة بالذكاء الاصطناعي', 'AI-augmented teams', 'الفرق المعززة بالذكاء الاصطناعي', 'Sets clear rules for when the team uses approved AI tools, expects outputs to be verified against the controlled source, and backs anyone who overrides a tool when something does not look right.', 'يضع قواعد واضحة لاستخدام الفريق لأدوات الذكاء الاصطناعي المعتمدة، ويتوقع التحقق من المخرجات مقابل المصدر المعتمد، ويساند كل من يتجاوز الأداة عندما يبدو أمر ما غير صحيح.', 'WEF Future of Jobs 2025: AI and big data is the fastest-growing skill (per source); the override rule follows the questioning attitude (INPO 12-012 trait 2)', 'تقرير مستقبل الوظائف 2025: الذكاء الاصطناعي والبيانات الضخمة الأسرع نمواً (وفق المصدر)؛ وقاعدة التجاوز امتداد للموقف التساؤلي (السمة 2 في INPO 12-012)', '{"1":{"en":"Lets people use AI tools without rules, or bans them without explanation.","ar":"يترك الناس يستخدمون أدوات الذكاء الاصطناعي بلا قواعد، أو يمنعها دون تفسير."},"2":{"en":"Knows the approved tools but does not talk about how outputs are checked.","ar":"يعرف الأدوات المعتمدة لكنه لا يتحدث عن كيفية التحقق من المخرجات."},"3":{"en":"Explains which tools are approved for which tasks and expects outputs to be verified against the controlled source.","ar":"يوضح الأدوات المعتمدة لكل مهمة ويتوقع التحقق من المخرجات مقابل المصدر المعتمد."},"4":{"en":"Sets clear override rules: anyone may stop and override a tool that disagrees with indications or procedures, and is thanked for it.","ar":"يضع قواعد تجاوز واضحة: يحق لأي شخص إيقاف الأداة وتجاوزها إذا خالفت المؤشرات أو الإجراءات، ويُشكر على ذلك."},"5":{"en":"Reviews AI-related near misses with the team, feeds lessons into the AI register and coaches others on human oversight.","ar":"يراجع مع الفريق الحوادث الوشيكة المرتبطة بالذكاء الاصطناعي، ويغذي سجل الذكاء الاصطناعي بالدروس، ويدرّب الآخرين على الإشراف البشري."}}'::jsonb, '{"tips":[{"en":"Agree with your team: an AI suggestion never replaces the procedure or the controlled source.","ar":"اتفق مع فريقك: اقتراح الذكاء الاصطناعي لا يحل محل الإجراء أو المصدر المعتمد أبداً."},{"en":"Praise, in front of the team, the first person who overrides a tool for a good reason.","ar":"امدح أمام الفريق أول شخص يتجاوز أداة لسبب وجيه."},{"en":"Review one AI-assisted task a month: what was checked, by whom, and what would have been missed.","ar":"راجع مهمة واحدة بمساعدة الذكاء الاصطناعي كل شهر: ما الذي تم التحقق منه، ومن قام به، وما الذي كان سيفوت."}],"practice":{"en":"This week: do a governed AI drill and talk the planted errors through with your team.","ar":"هذا الأسبوع: أدِّ تمريناً منضبطاً للذكاء الاصطناعي وناقش الأخطاء المزروعة مع فريقك."},"watch":{"en":"Automation bias grows when a tool is usually right.","ar":"يزداد الانحياز للأتمتة عندما تكون الأداة محقة في الغالب."}}'::jsonb, '[{"to":"/my/ai-fluency/drills","label_en":"Governed AI drills","label_ar":"تمارين الذكاء الاصطناعي المنضبطة"},{"to":"/my/ai-fluency","label_en":"My AI fluency","label_ar":"طلاقتي في الذكاء الاصطناعي"},{"to":"/workforce/ai-register","label_en":"AI-literacy register","label_ar":"سجل الإلمام بالذكاء الاصطناعي"}]'::jsonb, array['prog-future-leaders']::text[], array['WEF-FOJ']::text[], '[{"label":"WEF · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb),
('b-intrapreneurship', 2, 110, 'trait-8', 'Intrapreneurship', 'روح المبادرة داخل المؤسسة', 'Intrapreneurship', 'المبادرة', 'Spots chances to improve how ENEC works, gathers the resources and allies to test an idea safely, and turns it into action (EntreComp areas: ideas and opportunities, resources, into action).', 'يلتقط فرص تحسين طريقة عمل المؤسسة، ويجمع الموارد والحلفاء لاختبار الفكرة بأمان، ويحوّلها إلى عمل (مجالات EntreComp: الأفكار والفرص، والموارد، والتنفيذ).', 'EntreComp, the JRC framework in the same family as GreenComp and LifeComp (per source)', 'إطار EntreComp من مركز البحوث المشترك، من عائلة GreenComp وLifeComp نفسها (وفق المصدر)', '{"1":{"en":"Rarely suggests improvements and waits to be told.","ar":"نادراً ما يقترح تحسينات وينتظر التوجيه."},"2":{"en":"Shares ideas but does not follow them up.","ar":"يشارك الأفكار لكنه لا يتابعها."},"3":{"en":"Turns an idea into a small, safe trial with a clear owner and a check on the result.","ar":"يحوّل الفكرة إلى تجربة صغيرة وآمنة بمالك واضح وتحقق من النتيجة."},"4":{"en":"Builds a case with data, secures time and allies, and scales ideas that work through the change process.","ar":"يبني حجة بالبيانات ويؤمّن الوقت والحلفاء ويوسّع الأفكار الناجحة عبر عملية التغيير."},"5":{"en":"Creates room for others to experiment safely, sponsors their ideas and shares what failed as well as what worked.","ar":"يتيح للآخرين مساحة للتجريب الآمن ويرعى أفكارهم ويشارك ما فشل وما نجح."}}'::jsonb, '{"tips":[{"en":"Pick one friction in your area and write it as a problem statement, not a solution.","ar":"اختر عائقاً واحداً في نطاقك واكتبه كمشكلة لا كحل."},{"en":"Ask for a time envelope to test it, such as a future-skills gig or a small pilot.","ar":"اطلب نطاقاً زمنياً لاختباره، مثل مهمة مهارات مستقبلية أو تجربة صغيرة."},{"en":"Close the loop: share the result, even when the idea did not work.","ar":"أغلق الحلقة: شارك النتيجة حتى لو لم تنجح الفكرة."}],"practice":{"en":"This week: post an idea as a gig in the digital-innovation channel, or join one.","ar":"هذا الأسبوع: انشر فكرة كمهمة في قناة الابتكار الرقمي، أو انضم إلى إحداها."},"watch":{"en":"Never trial a change on plant equipment outside the formal modification process.","ar":"لا تجرّب أي تغيير على معدات المحطة خارج عملية التعديل الرسمية."}}'::jsonb, '[{"to":"/opportunities/future","label_en":"Future-skills gigs","label_ar":"مهام المهارات المستقبلية"},{"to":"/opportunities/envelope","label_en":"Ask for a time envelope","label_ar":"طلب نطاق زمني"},{"to":"/knowledge/capture","label_en":"Knowledge capture studio","label_ar":"استوديو توثيق المعرفة"}]'::jsonb, array['prog-future-leaders']::text[], array['GREENCOMP']::text[], '[{"label":"EU JRC · GreenComp (with EntreComp and LifeComp)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"}]'::jsonb),
('b-inclusion', 2, 120, 'trait-6', 'Inclusive leadership', 'القيادة الشاملة', 'Inclusion', 'الشمول', 'Makes sure every voice is heard whatever the person''s background, shift, grade or gender, shares opportunities fairly and acts on the barriers people raise.', 'يحرص على سماع كل صوت أياً كانت خلفية الشخص أو ورديته أو درجته أو جنسه، ويوزع الفرص بإنصاف، ويعالج العوائق التي يطرحها الناس.', 'OECD-NEA Plan 2035: mentor and network lanes for the nuclear workforce (per source)', 'خطة 2035 لوكالة الطاقة النووية: مسارا الإرشاد والشبكات للقوى العاملة النووية (وفق المصدر)', '{"1":{"en":"The same few people speak and get the opportunities.","ar":"يتحدث الأشخاص القلائل أنفسهم ويحصلون على الفرص."},"2":{"en":"Is fair when asked but does not notice who is left out.","ar":"منصف عندما يُطلب منه، لكنه لا يلاحظ من يُستبعد."},"3":{"en":"Invites quieter voices in meetings and rotates stretch opportunities across the team.","ar":"يدعو الأصوات الأهدأ في الاجتماعات ويدوّر الفرص التطويرية على الفريق."},"4":{"en":"Checks who gets development and visibility, removes barriers people raise and mentors across backgrounds.","ar":"يتحقق ممن يحصل على التطوير والظهور، ويزيل العوائق المطروحة، ويرشد أشخاصاً من خلفيات مختلفة."},"5":{"en":"Builds a team where people of different backgrounds lead, sponsors under-represented talent and is a role model across ENEC.","ar":"يبني فريقاً يقوده أشخاص من خلفيات مختلفة، ويرعى المواهب الأقل تمثيلاً، ويكون قدوة في المؤسسة."}}'::jsonb, '{"tips":[{"en":"In your next brief, ask the person who has not spoken yet first.","ar":"في إحاطتك القادمة، اسأل أولاً من لم يتحدث بعد."},{"en":"Look at who led the last three stretch tasks and offer the next one to someone else.","ar":"انظر إلى من قاد آخر ثلاث مهام تطويرية واعرض التالية على شخص آخر."},{"en":"Offer to mentor, or sponsor a mentor circle outside your own group.","ar":"تطوّع للإرشاد، أو ارعَ حلقة إرشاد خارج مجموعتك."}],"practice":{"en":"This week: open a mentor circle seat in the women in future nuclear skills network, or ask how to sponsor one.","ar":"هذا الأسبوع: افتح مقعداً في حلقة إرشاد ضمن شبكة المرأة في المهارات النووية المستقبلية، أو اسأل كيف ترعى حلقة."},"watch":{"en":"Inclusion is about access to opportunities, never about scores: no ranking in Kafa''a uses gender or nationality.","ar":"الشمول يتعلق بالوصول إلى الفرص لا بالدرجات: لا يستخدم أي ترتيب في كفاءة الجنس أو الجنسية."}}'::jsonb, '[{"to":"/communities/women-in-nuclear","label_en":"Women in future nuclear skills","label_ar":"المرأة في المهارات النووية المستقبلية"},{"to":"/my/mentoring","label_en":"My mentoring","label_ar":"الإرشاد الخاص بي"}]'::jsonb, array['prog-future-leaders']::text[], array['NEA']::text[], '[{"label":"OECD-NEA · Plan 2035 vision paper (NEST)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10"}]'::jsonb)
